	"TENANT_ID" NUMBER(20,0) DEFAULT 3 NOT NULL ENABLE,                                                                                                                                                           
	"REMARK" NVARCHAR2(512),                                                                                                                                                                                      
	"SUBMIT_USER_ID" NUMBER(20,0),                                                                                                                                                                                
	"SUBMIT_EXT_ORG_ID" NUMBER(20,0),                                                                                                                                                                             
	"CONTENT" CLOB,                                                                                                                                                                                               
	"CURRENT_PAGE_URL" NVARCHAR2(512),                                                                                                                                                                            
	"CURRENT_PAGE_NAME" NVARCHAR2(100),                                                                                                                                                                           
	"IMAGES_URLS" CLOB,                                                                                                                                                                                           
	"STATUS" NVARCHAR2(20),                                                                                                                                                                                       
	"REPLY_EXT_USER_ID" NUMBER(20,0),                                                                                                                                                                             
	"REPLAY_CONTENT" NVARCHAR2(1000),                                                                                                                                                                             
	"BASE_DEPT_ID" NVARCHAR2(36),                                                                                                                                                                                 
	 PRIMARY KEY ("FEEDBACK_ID")                                                                                                                                                                                  
